<tr><td style="padding:4px 0;color:#555">Pickup</td><td style="padding:4px 0">28 Apr 2026, 09:00</td></tr>
<tr><td style="padding:4px 0;color:#555;vertical-align:top">Route</td><td style="padding:4px 0">O.R. Tambo International Airport → 41 Terrace Road</td></tr>
<tr><td style="padding:4px 0;color:#555">Vehicle class</td><td style="padding:4px 0">—</td></tr>
<tr><td style="padding:4px 0;color:#555">Passengers</td><td style="padding:4px 0">1</td></tr>
<tr><td style="padding:4px 0;color:#555">Total</td><td style="padding:4px 0"><strong>R 20 000,00</strong></td></tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:13px;margin-bottom:20px">
<thead><tr>
